<script setup lang="ts">
import AppIcon from '../components/AppIcon.vue'
import PageHeader from '../components/PageHeader.vue'
import AppModal from '../components/AppModal.vue'
import EmptyState from '../components/EmptyState.vue'
import { onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api, errorText, formatTime } from '../lib/api'
const categories = ['经济','科技','教育','基层治理','乡村振兴','生态文明','文化','社会治理','民生','数字政府']
const kinds = ['案例','政策','金句','观点','数据','人物案例']
interface Material { id: string; title: string; content: string; category: string; kind: string; tags: string[]; source: string; sourceUrl: string | null; publishTime: string | null; fetchTime: string; sourceUnverified: boolean }
const route = useRoute(), items = ref<Material[]>([]), total = ref(0), page = ref(1), q = ref(''), category = ref(''), kind = ref(''), error = ref(''), open = ref(false), editing = ref(''), busy = ref(false), loading = ref(true)
const initial = () => ({ title: '', content: '', category: '基层治理', kind: '案例', tags: '', source: '', sourceUrl: '', publishTime: '', sourceUnverified: true })
const form = ref(initial())
async function load(reset = false) { if (reset) page.value = 1; loading.value = true; try { if (route.params.id) { items.value = [(await api.get<Material>('/essay-materials/' + route.params.id)).data]; total.value = 1 } else { const { data } = await api.get('/essay-materials', { params: { q: q.value, category: category.value, kind: kind.value, page: page.value } }); items.value = data.items; total.value = data.total }; error.value = '' } catch (e) { error.value = errorText(e) } finally { loading.value = false } }
function edit(item?: Material) { editing.value = item?.id || ''; form.value = item ? { ...item, tags: item.tags.join('，'), sourceUrl: item.sourceUrl || '', publishTime: item.publishTime ? new Date(new Date(item.publishTime).getTime() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0,16) : '' } : initial(); open.value = true }
async function save() { busy.value = true; try { const body = { ...form.value, tags: form.value.tags.split(/[，,、\n]/).map(x => x.trim()).filter(Boolean), sourceUrl: form.value.sourceUrl || null, publishTime: form.value.publishTime ? new Date(form.value.publishTime).toISOString() : null }; if (editing.value) await api.put('/essay-materials/' + editing.value, body); else await api.post('/essay-materials', body); open.value = false; await load() } catch (e) { error.value = errorText(e) } finally { busy.value = false } }
async function remove(id: string) { if (confirm('删除这条申论素材？')) try { await api.delete('/essay-materials/' + id); await load() } catch (e) { error.value = errorText(e) } }
onMounted(() => load())
</script>
<template><PageHeader title="申论素材库"><template #description><p class="muted">共 {{ total }} 条素材</p></template><button class="button" @click="edit()"><AppIcon name="plus" :size="17" />添加素材</button></PageHeader><form v-if="!route.params.id" class="toolbar" @submit.prevent="load(true)"><input v-model="q" placeholder="查找主题、内容或标签" aria-label="查找素材"><select v-model="category" aria-label="素材分类" @change="load(true)"><option value="">全部分类</option><option v-for="name in categories" :key="name">{{ name }}</option></select><select v-model="kind" aria-label="素材类型" @change="load(true)"><option value="">全部类型</option><option v-for="name in kinds" :key="name">{{ name }}</option></select><button class="button secondary">查找</button></form><RouterLink v-else class="text-button" to="/materials">返回素材库</RouterLink><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="loading-state" role="status">正在读取素材…</p><EmptyState v-else-if="!items.length && !error" :title="q || category || kind ? '没有找到相关素材' : '暂无申论素材'" :description="q || category || kind ? '换个主题查找，或清除分类与类型筛选。' : '保存案例、政策或观点，并注明来源。'" icon="folder"><button v-if="q || category || kind" class="button secondary" @click="q = ''; category = ''; kind = ''; load(true)">清除筛选</button><button v-else class="button" @click="edit()">添加素材</button></EmptyState><article v-for="item in items" :key="item.id" class="panel section-gap material-card"><div class="panel-heading"><h2>{{ item.title }}</h2><div class="actions"><button class="text-button" @click="edit(item)">编辑</button><button class="text-button danger" @click="remove(item.id)">删除</button></div></div><div class="actions"><span class="tag">{{ item.category }}</span><span class="tag neutral">{{ item.kind }}</span><span v-for="tag in item.tags" :key="tag" class="tag neutral"># {{ tag }}</span></div><p class="reading">{{ item.content }}</p><p class="muted"><a v-if="item.sourceUrl" :href="item.sourceUrl" class="text-button" target="_blank" rel="noopener noreferrer">{{ item.source || '查看原始来源' }}</a><span v-else>{{ item.source || '用户笔记' }}</span> · {{ item.sourceUnverified ? '来源待核实' : '已记录来源' }} · 发布：{{ formatTime(item.publishTime) }} · 收录：{{ formatTime(item.fetchTime) }}</p></article><div v-if="total > 20" class="pagination"><button class="button secondary" :disabled="page === 1" @click="page--; load()">上一页</button><span>{{ page }} / {{ Math.ceil(total / 20) }}</span><button class="button secondary" :disabled="page * 20 >= total" @click="page++; load()">下一页</button></div><AppModal v-model:open="open" :title="editing ? '编辑素材' : '保存申论素材'" :busy="busy"><form @submit.prevent="save"><h2>{{ editing ? '编辑素材' : '保存申论素材' }}</h2><label>标题<input v-model="form.title" required maxlength="300"></label><div class="form-grid"><label>分类<select v-model="form.category"><option v-for="name in categories" :key="name">{{ name }}</option></select></label><label>类型<select v-model="form.kind"><option v-for="name in kinds" :key="name">{{ name }}</option></select></label></div><label>素材内容<textarea v-model="form.content" required rows="7" maxlength="20000"></textarea></label><label>标签（逗号分隔）<input v-model="form.tags"></label><label>来源<input v-model="form.source" maxlength="200"></label><label>来源链接<input v-model="form.sourceUrl" type="url" placeholder="https://" maxlength="2000"></label><label>发布时间<input v-model="form.publishTime" type="datetime-local"></label><label class="checkbox-label"><input v-model="form.sourceUnverified" type="checkbox">来源尚待核实</label><p v-if="error" class="error">{{ error }}</p><div class="actions"><button type="button" class="button secondary" :disabled="busy" @click="open = false">取消</button><button class="button" :disabled="busy">保存素材</button></div></form></AppModal></template>
